def transform(grid):
    h, w = len(grid), len(grid[0])

    # The most frequent color is the background; full lines of another color
    # are the dividers.
    counts = [0] * 10
    for row in grid:
        for value in row:
            counts[value] += 1
    background = max(range(10), key=lambda value: counts[value])

    row_cuts = [
        r for r in range(h)
        if all(value == grid[r][0] for value in grid[r])
        and grid[r][0] != background
    ]
    col_cuts = [
        c for c in range(w)
        if all(grid[r][c] == grid[0][c] for r in range(h))
        and grid[0][c] != background
    ]

    row_bounds = [-1] + row_cuts + [h]
    col_bounds = [-1] + col_cuts + [w]
    regions = []

    for i in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[i] + 1, row_bounds[i + 1]
        for j in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[j] + 1, col_bounds[j + 1]
            tile = [grid[r][c0:c1] for r in range(r0, r1)]
            filled = sum(v != background for row in tile for v in row)
            regions.append((r0, r1, c0, c1, tile, filled))

    source = max(regions, key=lambda region: region[5])
    sr0, sr1, sc0, sc1, tile, _ = source
    out = [row[:] for row in grid]

    for r0, r1, c0, c1, _, _ in regions:
        if (r0, r1, c0, c1) == (sr0, sr1, sc0, sc1):
            continue
        if r1 - r0 == len(tile) and c1 - c0 == len(tile[0]):
            for dr in range(len(tile)):
                for dc in range(len(tile[0])):
                    out[r0 + dr][c0 + dc] = tile[dr][dc]

    return out
